import java.util.Scanner;

public class Test {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        while (s.hasNextLine()) {
            s.nextLine();
            System.out.println(TextDocumentAnalysis.input(s.nextLine()));
        }
        s.close();
    }
}

class TextDocumentAnalysis {
    public static String input(String str) {
        int max = 0;
        int words = 0;
        int len = 0;
        boolean inside = false;
        for (char c : str.toCharArray()) {
            switch (c) {
                case '(':
                    if (len > 0) {
                        if (len > max) max = len;
                        len = 0;
                    }
                    inside = true;
                    break;
                case ')':
                    if (len > 0) {
                        words++;
                        len = 0;
                    }
                    inside = false;
                    break;
                case '_':
                    if (len > 0) {
                        if (inside) words++;
                        else if (len > max) max = len;
                        len = 0;
                    }
                    break;
                default:
                    len++;
                    break;
            }
        }
        if (len > 0) {
            if (inside) words++;
            else if (len > max) max = len;
        }
        return max + " " + words;
    }
}
